---检查个人mbox掉落记录c重置
function MonsterScript.ResetDecayMboxRecordCheck(actor)
    local decayMboxResetRecord = getplaydef(actor, DECAY_MBOX_RESET_RECORD) or 0
    --计算buff倍率
    local globalbuff = ConfigDataManager.getTableValue("cfg_global", "value", "id", GlobalConfigId.DROP_BUFF_GOLOBAL_RECORD)
    globalbuff = string.toIntIntMap(globalbuff)
    local buff_multi = 1
    for buff_id, rate in pairs(globalbuff) do
        if hasbuff(actor, buff_id) then
            buff_multi = buff_multi + tonumber(rate) - 1
        end
    end
    local reset_time = decayMboxResetRecord
    local cur_time = getbaseinfo(actor, "nowsec")
    local zero_time = TimeUtil.creteTimeDayStart4Sec(cur_time)
    local reset_cfg = ConfigDataManager.getTableValue("cfg_global", "value", "id", GlobalConfigId.PLAYER_DROP_MBOX_RESET_TIEM)
    reset_cfg = string.split(reset_cfg, "#")
    local change = false
    if #reset_cfg > 1 then
        --遍历重置时间配置
        for i = #reset_cfg, 1, -1 do
            local reset_sec = zero_time + math.ceil(tonumber(reset_cfg[i]) * 60 / buff_multi)
            -- info("个人mbox掉落记录重置1", os.date("%Y-%m-%d %H:%M:%S", reset_sec),buff_multi,math.ceil(tonumber(reset_cfg[i])*60/buff_multi))
            if cur_time >= reset_sec then
                if reset_sec > reset_time then
                    change = true
                    reset_time = reset_sec
                end
                break;
            end
        end
    else
        local jiange_sec = math.ceil(tonumber(reset_cfg[1]) * 60 / buff_multi)
        if cur_time > reset_time + jiange_sec then
            change = true
            reset_time = zero_time + (math.ceil((cur_time - zero_time) / jiange_sec)) * jiange_sec
        end
    end
    -- info("个人mbox掉落记录重置2", os.date("%Y-%m-%d %H:%M:%S", os.time()), os.date("%Y-%m-%d %H:%M:%S", reset_time))
    if change then
        info("个人mbox掉落记录重置", os.date("%Y-%m-%d %H:%M:%S", os.time()), os.date("%Y-%m-%d %H:%M:%S", reset_time))
        setplaydef(actor, DECAY_MBOX_RESET_RECORD, reset_time)
        this.SaveDecayMboxRecord(actor, nil)
    end
end





---检查全服mbox掉落记录重置
function MonsterScript.ResetGlobalDecayMboxRecordCheck()
    local globalDecayMboxResetRecord = getsysvar(WORLD_DECAY_MBOX_RESET_RECORD) or 0
    local resetCount = globalDecayMboxResetRecord
    local currentTime = getbaseinfo("nowsec")
    local zeroTime = TimeUtil.creteTimeDayStart4Sec(currentTime)
    local resetConfig = ConfigDataManager.getTableValue("cfg_global", "value", "id", GlobalConfigId.WORLD_DROP_MBOX_RESET_TIEM)
    resetConfig = string.split(resetConfig, "#")
    local nextResetTime = 0
    if #resetConfig > 1 then
        -- 多个配置，按照指定时间点重置，只在当天生效
        if resetConfig[resetCount + 1] ~= nil then
            nextResetTime = zeroTime + tonumber(resetConfig[resetCount + 1]) * 60
        else
            -- 已经超过所有指定时间点
            nextResetTime = zeroTime + 24 * 60 * 60
        end
    else
        -- 单个配置，每隔指定时间重置一次
        local intervalMin = tonumber(resetConfig[1])
        local currentMin = math.floor((currentTime - zeroTime) / 60)
        nextResetTime = zeroTime + intervalMin * 60 * (resetCount + 1)
        local currentResetCount = math.floor(currentMin / intervalMin)
        if currentResetCount > resetCount then
            resetCount = currentResetCount
        end
    end
    -- info("全服mbox掉落记录重置1", os.date("%Y-%m-%d %H:%M:%S", os.time()), os.date("%Y-%m-%d %H:%M:%S", nextResetTime),resetCount)
    if currentTime > nextResetTime then
        -- jprint("全服mbox掉落记录重置", resetCount)
        setsysvar(WORLD_DECAY_MBOX_RESET_RECORD, resetCount + 1)
        if next(ALL_M_GROUP_CACHE) == nil then
            local list = ConfigDataManager.getList('cfg_Monster_mboxDecay')
            for _, cfg in pairs(list) do
                if not table.contains(ALL_M_GROUP_CACHE, tonumber(cfg.group)) then
                    table.insert(ALL_M_GROUP_CACHE, tonumber(cfg.group))
                end
            end
        end

        for _, group in pairs(ALL_M_GROUP_CACHE) do
            setsysvar(WORLD_DECAY_MBOX_GROUP_RECORD_BY_GROUP .. group, 0)
        end
    end
end

