---获取属性倍率
function this.GetAttrDropRate(actor)
    local attrRate = tonumber(getattrinfo(actor, "propdropincrease"))
    DropLog.addLog("属性propdropincrease的倍率加成：" .. attrRate)
    if attrRate == nil then
