---获取一个掉落组中的配置列表
function this.GetDropCfgList(data)
    local cfgList = ConfigDataManager.getTable('cfg_boss_drop', 'mgroup', data.group)
    if table.isNullOrEmpty(cfgList) then
        return nil
    end
    local dropCfgList = {}
    for _, dropBossCfg in pairs(cfgList) do
        local dropParam = this.GetDropCfg(data, dropBossCfg)
        if not table.isNullOrEmpty(dropParam) then
            local dropCfgId = tonumber(dropBossCfg["id"])
            dropCfgList[dropCfgId] = dropParam
        end
    end
    return dropCfgList
end

---获取一个掉落配置
function this.GetDropCfg(data, dropCfg)
    local numLimit = string.split(dropCfg['dropnum'], "#")
    local min = tonumber(numLimit[1])
    local max = tonumber(numLimit[2])
    if max == 999999 then
        --999999标识无限大
        if data.startCount < min then
            return nil
        end
    else
        if data.startCount < min or data.startCount > max then
            return nil
        end
    end

    --新版代码 begin
    local moboxid = dropCfg["moboxid"]
    if string.isNullOrEmpty(moboxid) then
        return nil
    end
    --掉落次数衰减
    local killgroupRate = this.CulKillGroupRate(dropCfg, data.kill_record)
    --个人mbox衰减
    local playmboxrate = this.CulPlayMboxRate(data.playerDecayMboxRecord, dropCfg)
    --全服mbox衰减
    local globalmboxrate = this.CulGlobalMboxRate( dropCfg)
    --新版代码 end
    local dropRate = this.CulDropRate(data, dropCfg)
    local extractNum = tonumber(dropCfg["extractnum"])
    -- 掉落改版之前代码 begin
    -- local itemGroup = dropCfg["itemgroup"]
    -- if string.isNullOrEmpty(itemGroup) then
    --     local randomGroupCfg = dropCfg["itemgrouprandom"]
    --     local tableName,addExtract = this.GetRandomItemGroup(randomGroupCfg,dropRate,itemGroupDecayCfg)
    --     if addExtract ~= nil and addExtract > 0 then
    --         itemGroup = tableName
    --         extractNum = extractNum * addExtract
    --     end
    -- end
    -- if string.isNullOrEmpty(itemGroup) then
    --     return nil
    -- end
    -- 掉落改版之前代码 end
    local dropParam = {
        id = tonumber(dropCfg["id"]),
        -- 掉落改版之前代码
        -- table_name = itemGroup,
        -- 掉落改版之前代码 end
        -- 新版代码 begin
        moboxid = moboxid,
        -- 新版代码 end
        extract_times = extractNum,
        rate = dropRate,
        killgrouprate = killgroupRate,
        playmboxrate = playmboxrate,
        globalmboxrate = globalmboxrate,
    }
    DropLog.addLog("★★★★★★★★★★★★★★★★★★★★")
    return dropParam
end

---获取配置的随机道具组
function this.GetRandomItemGroup(randomGroupCfg, dropRate, itemGroupDecayCfg)
    if string.isNullOrEmpty(randomGroupCfg) then
        return nil
    end
    local itemGroupCfg = string.split(randomGroupCfg, "#")
    local tableName = itemGroupCfg[1]
    ---随机概率万分比
    local probabilityCfg = tonumber(itemGroupCfg[2])
    local percent = 10000
    local extractNum = 0
    local decayRate = this.GetItemGroupDecayRate(tableName, itemGroupDecayCfg)
    local realProbability = probabilityCfg * dropRate * decayRate
    --jprint("随机掉落组配置：", tableName,dropRate,decayRate, realProbability)
    if realProbability >= percent then
        extractNum = math.floor(realProbability / percent)
        realProbability = math.fmod(realProbability, percent)
    end

    local randomNum = math.random(1, percent)
    if randomNum <= realProbability then
        extractNum = extractNum + 1
    end
    --jprint("随机掉落组配置：", tableName, extractNum,realProbability)
    return tableName, extractNum
end

function this.GetItemGroupDecayRate(tableName, itemGroupDecayCfg)
    if table.isNullOrEmpty(itemGroupDecayCfg) then
        return 1
    end
    for tableNames, rate in pairs(itemGroupDecayCfg) do
        if string.contains(tableNames, tableName) then
            return rate
        end
    end
    return 1
end

---计算最终掉落倍率
function this.CulDropRate(data, dropCfg)
    local finalRate = data.bonusRate
    local lvDecaySign = dropCfg["decaysign"]
    DropLog.addLog(string.format("cfg_boss_drop配置[%d],等级衰减字段配置decaysign为[%s]", dropCfg.id, lvDecaySign))
    --掉落等级衰减
    finalRate = this.CulLevelRate(data.killerLv, data.monsterLv, lvDecaySign, finalRate)
    DropLog.addLog("角色倍率 = 原角色倍率*掉落等级衰减 最终为" .. (finalRate))
    return finalRate
end

---获取死亡组掉落倍率
function this.CulKillGroupRate(dropCfg, kill_record)
    -- info("kill_record:", kill_record)
    local contorlList = string.split(dropCfg["killcontrol"], "|")
    local killgroup = dropCfg["killgroup"]
    if string.isNullOrEmpty(killgroup) then
        return 1
    end
    --这里是10万分比
    local minrate = 100000
    for _, contorl in pairs(contorlList) do
        local contorlSplit = string.split(contorl, "#")
        local killnum = tonumber(contorlSplit[1])
        -- info("killnum:", killnum,"kill_record[killgroup]:", kill_record[killgroup])
        if killnum <= kill_record[killgroup] then
            local rate = tonumber(contorlSplit[2])
            minrate = math.min(minrate, rate)
        end
    end
    -- info("killgroupTime:", tostring(killgroupTime),"minrate:", tostring(minrate))
    return minrate / 100000
end

---获取个人mbox衰减倍率
function this.CulPlayMboxRate(playerDecayMboxRecord, dropCfg)
    -- info("获取个人mbox衰减倍率:1")
    local mboxId = dropCfg["moboxid"]
    if string.isNullOrEmpty(mboxId) then
        -- info("获取个人mbox衰减倍率:2",dropCfg)
        return 1
    end
    local box_group = ConfigDataManager.getTableValue('cfg_Monster_mboxDecay', 'group', 'id', mboxId)
    local count = playerDecayMboxRecord[box_group]
    if count == nil then
        count = 0
    end
    count = count + 1
    --这里是10万分比
    local minrate = 100000
    local playcontrol = ConfigDataManager.getTableValue('cfg_Monster_mboxDecay', 'playcontrol', 'id', mboxId)
    local contorlList = string.split(playcontrol, "|")
    for _, contorl in pairs(contorlList) do
        local contorlSplit = string.split(contorl, "#")
        local killnum = tonumber(contorlSplit[1])
        if killnum <= count then
            local rate = tonumber(contorlSplit[2])
            minrate = math.min(minrate, rate)
        end
    end
    -- info("获取个人mbox衰减倍率3:", playerDecayMboxRecord,contorlList)
    return minrate / 100000
end

---获取全服mbox衰减倍率
function this.CulGlobalMboxRate(dropCfg)
    local mboxId = dropCfg["moboxid"]
    if string.isNullOrEmpty(mboxId) then
        return 1
    end
    local box_group = ConfigDataManager.getTableValue('cfg_Monster_mboxDecay', 'group', 'id', mboxId)
    local count = getsysvar(WORLD_DECAY_MBOX_GROUP_RECORD_BY_GROUP .. box_group)
    if count == nil then
        count = 0
    end
    count = count + 1
    --这里是10万分比
    local minrate = 100000
    local globalcontrol = ConfigDataManager.getTableValue('cfg_Monster_mboxDecay', 'globalcontrol', 'id', mboxId)
    local contorlList = string.split(globalcontrol, "|")
    for _, contorl in pairs(contorlList) do
        local contorlSplit = string.split(contorl, "#")
        local killnum = tonumber(contorlSplit[1])
        if killnum <= count then
            local rate = tonumber(contorlSplit[2])
            minrate = math.min(minrate, rate)
        end
    end
    return minrate / 100000
end

---获取配置掉落概率
function this.GetLevelRateCfg(killerLv, monsterLv, decayCfg)
    local roleSection = string.split(decayCfg["rolesection"], "#")
    local roleLvMin = tonumber(roleSection[1])
    local roleLvMax = tonumber(roleSection[2])
    if killerLv < roleLvMin or killerLv > roleLvMax then
        return nil
    end
    local monsterSection = string.split(decayCfg["monstersection"], "#")
    local monsterLvMin = tonumber(monsterSection[1])
    local monsterLvMax = tonumber(monsterSection[2])
    if monsterLv < monsterLvMin or monsterLv > monsterLvMax then
        return nil
    end
    return tonumber(decayCfg["dropdecayrate"])
end

function this.CulLevelRate(killerLv, monsterLv, decaySign, roleRate)
    local cfgList = ConfigDataManager.getTable('cfg_boss_dropDecay', 'decaysign', decaySign)
    if table.isNullOrEmpty(cfgList) then
        DropLog.addLog("无掉落衰减倍率，默认为 1")
        return roleRate
    end
    for _, decayCfg in pairs(cfgList) do
        local rateCfg = this.GetLevelRateCfg(killerLv, monsterLv, decayCfg)
        if rateCfg ~= nil then
            DropLog.addLog(string.format("玩家等级[%d]，怪物等级[%d]，取到cfg_boss_dropDecay表的dropdecayrate字段，掉落衰减倍率为[%.4f]", killerLv, monsterLv, (rateCfg / 10000)))
            return roleRate * (rateCfg / 10000)
        end
    end
    DropLog.addLog("无掉落衰减倍率，默认为 1")
    return roleRate
end

