function this.GetDropResult(dieParam, actor, monsterActor, data)
    --随机道具
    for dropGroup, dropCfgList in pairs(data.allDropCfg) do
        local dropCount = data.dropRecord[dropGroup]
        if dropCount == nil then
            dropCount = 0
        end
        if not table.isNullOrEmpty(dropCfgList) then
            for dropCfgId, dropCfg in pairs(dropCfgList) do
                this.CulDropItem(dieParam, actor, monsterActor, dropCfg, dropCount, data)
            end
        end
        --记录掉落次数
        data.dropRecord[dropGroup] = dropCount + 1
    end
end

