---随机掉落道具
function this.RandomDropItem(dieParam, actor, monsterActor, dropCfg, dropCount, data)
    local dropRate = dropCfg.rate
    -- 掉落改版之前代码 begin
    -- local tableName = dropCfg.table_name
    -- local dropRet = culdroptablebyname(actor,tableName,dropRate,dropCount,itemDecay)
    -- if dropRet == false or table.isNullOrEmpty(dropRet) then
    --     return
    -- end
    -- 掉落改版之前代码 end
    -- 新版代码 begin dropCount本版本不使用
    local moboxid = dropCfg.moboxid
    local moboxPro_ = tonumber(ConfigDataManager.getTableValue('cfg_boss_drop', 'moboxPro', 'id', dropCfg.id))
    if string.isNullOrEmpty(moboxPro_) then
        DropLog.addLog(string.format("掉落配置[%d] - 未找到moboxPro配置", dropCfg.id))
        DropLog.addLog("★★★★★★★★★★★★★★★★★★★★")
        return
    end
    local dropincrease = ConfigDataManager.getTableValue('cfg_boss_drop', 'dropincrease', 'id', dropCfg.id)
    --buff掉落倍率
    local buffDropRate = this.CulBuffDropRate(actor, dropincrease)
    local killgroupRate = dropCfg.killgrouprate
    local playmboxrate = dropCfg.playmboxrate
    local globalmboxrate = dropCfg.globalmboxrate
    local moboxPro = (tonumber(moboxPro_) * dropRate * killgroupRate * playmboxrate * globalmboxrate)
    moboxPro = moboxPro + moboxPro * buffDropRate
    DropLog.addLog(string.format("掉落配置[%d] - 基础概率:%.2f, 角色倍率:%.2f, 击杀组衰减:%.2f, 个人mbox衰减:%.2f, 全服mbox衰减:%.2f, buff倍率:%.2f, 最终概率:%.2f",
        dropCfg.id, moboxPro_, dropRate, killgroupRate, playmboxrate, globalmboxrate, buffDropRate, moboxPro))
    local yi = 100000000
    --是否掉落 亿分比
    local randomNum = math.random(1, yi)

    if moboxPro < yi and randomNum > moboxPro then
        DropLog.addLog(string.format("掉落配置[%d] - 随机数[%.2f] > 概率[%.2f], 未掉落", dropCfg.id, randomNum, moboxPro))
        DropLog.addLog("★★★★★★★★★★★★★★★★★★★★")
        return
    end
    DropLog.addLog(string.format("掉落配置[%d] - 随机数[%.2f] <= 概率[%.2f], 通过掉落检测", dropCfg.id, randomNum, moboxPro))
    info("moboxPro:", tostring(moboxPro), "randomNum:", tostring(randomNum))
    local extractTimes = dropCfg.extract_times
    local extract_pro = 0
    if moboxPro > yi then
        extractTimes = extractTimes + math.floor(moboxPro / yi) - 1
        extract_pro = moboxPro % yi
        DropLog.addLog(string.format("掉落配置[%d] - 概率超过亿分比, 额外抽取次数:%d, 额外概率:%.2f", dropCfg.id, math.floor(moboxPro / yi) - 1, extract_pro))
    end
    DropLog.addLog(string.format("掉落配置[%d] - 最终抽取次数:%d", dropCfg.id, extractTimes))
    local dropRet, boxByItem = this.getdropitem(actor, moboxid, extractTimes, extract_pro)
    --掉落道具数量
    local box_group = ConfigDataManager.getTableValue('cfg_Monster_mboxDecay', 'group', 'id', moboxid)
    -- info("box_group:", box_group,"moboxid",moboxid)
    local dropItem = dropRet
    DropLog.addLog(string.format("掉落配置[%d] - 原始掉落结果:%s", dropCfg.id, table.toString(dropRet, true)))
    data.playerDecayMboxRecord[box_group] = (data.playerDecayMboxRecord[box_group] or 0) + 1
    opsysvar(WORLD_DECAY_MBOX_GROUP_RECORD_BY_GROUP .. box_group, 1, 1)
    -- info("掉落道具：", dropItem)
    -- 新版代码 end
    local bossDropCfgId = dropCfg.id
    if table.isNullOrEmpty(dropItem) then
        DropLog.addLog(string.format("掉落配置[%d] - 最终无掉落", dropCfg.id))
        DropLog.addLog("★★★★★★★★★★★★★★★★★★★★")
        return
    end
    DropLog.addLog(string.format("掉落配置[%d] - 最终掉落完成, 掉落结果:%s", dropCfg.id, table.toString(dropItem, true)))
    --掉落道具
    if data.gmInfo == nil then
        local firstAttack = tonumber(getbaseinfo(actor, "rid"))
        local mapId = tonumber(dieParam["mapid"])
        local mainOwner, owners = this.SettingOwners(monsterActor, dieParam, bossDropCfgId, firstAttack)
        -- 掉落物品来源信息
        local fromData = ItemFrom.genericDropInfo(mapId, dieParam.monstercfg, dieParam.killer)
        local extDataMap = {}        
        for itemId, count in pairs(dropItem) do
            local mboxCfg = boxByItem[itemId]
            local extData = {}
            table.merge(extData, fromData)
            if table.notEmpty(mboxCfg) then
                local extData0 = Equip_PuTong.qzEquipAtt(itemId, mboxCfg, 0)
                --info(actor, "玩家", actor, "触发掉落随机相关 掉落 cfgId：", itemId ,"内容：", extData0)
                table.merge(extData, extData0)
                if not string.isNullOrEmpty(mboxCfg.broadcast) then
                    extData.dropTip = tonumber(mboxCfg.broadcast)
                    extData.killerId = string.tonumber(dieParam.killer)
                end
            end
            extDataMap[itemId] = extData
        end
        if dropItem[1031] then
            info(actor, "掉落道具：", dropItem)
        end
        local ret = monsterdiedroptomap(monsterActor, mapId, bossDropCfgId, dropItem, mainOwner, owners, extDataMap)
        
        if ret == false or ret == nil then
            DropLog.addLog(string.format("掉落配置[%d] - 发送掉落道具失败", dropCfg.id))
            DropLog.addLog("★★★★★★★★★★★★★★★★★★★★")
            return
        end
        DropLog.addLog(string.format("掉落配置[%d] - 发送掉落道具成功", dropCfg.id))
        DropLog.addLog("★★★★★★★★★★★★★★★★★★★★")
    else
        ---gm记录掉落组触发次数
        local oldCount = data.gmInfo[moboxid] or 0
        data.gmInfo[moboxid] = oldCount + 1
    end
    --记录道具抽取次数
    this.MergeDropItem(dropItem,  data.dropResult)
end

function this.CulBuffDropRate(actor, dropincrease)
    local buffDropRate = 0
    local buffList = string.toIntIntMap(dropincrease)
    -- info("buffList", buffList)
    for buff_id, rate in pairs(buffList) do
        local buffId = tonumber(buff_id)
        if hasbuff(actor, buffId) then
            buffDropRate = buffDropRate + (tonumber(rate) / 100000) - 1
        end
    end
    return buffDropRate
end

function this.getdropitem(actor, moboxid, extractTimes, extract_pro)
    extractTimes = extractTimes or 1
    local dropItem = {}
    local boxByItem = {}
    local cfgList = ConfigDataManager.getTable('cfg_Monster_mbox', 'mboxId', moboxid)
    if table.isNullOrEmpty(cfgList) then
        info("不掉落，cfgList为空:", tostring(moboxid))
        return
    end
    -- info("掉落，cfgList:",cfgList)
    local total_weight = 0
    local list = {}
    for _, mboxCfg in pairs(cfgList) do
        --检查掉落条件
        local condition = mboxCfg.condition
        if not string.isNullOrEmpty(condition) then
            -- local conditionSplit = string.split(condition, "&")
            -- for i = 1, #conditionSplit do
            --     local condition = string.split(conditionSplit[i], "#")
            --     if not ConditionHandler:triggerCheck(condition[1], actor, condition[2]) then
            --         -- info("不掉落1，" .. mboxCfg.itemid .. "condition:", tostring(condition[1]), tostring(condition[2]))
            --         goto continue
            --     end
            -- end
            local check = ConditionManager.Check(actor, condition)
            if not check then
                goto continue
            end
        end
        if string.isNullOrEmpty(mboxCfg.count) then
            -- info("不掉落2，" .. mboxCfg.itemid .. "count为空:", tostring(mboxCfg.count))
            goto continue
        end
        --判断职业
        if not string.isNullOrEmpty(mboxCfg.career) then
            local careermap = string.toIntIntMap(mboxCfg.career)
            local career = tonumber(getbaseinfo(actor, "getbasecareer"))
            local careerRank = tonumber(getbaseinfo(actor, "getcareerrank"))
            if careermap[career] == nil then
                -- info("不掉落3，career为空:", tostring(career), mboxCfg.career)
                goto continue
            end
            if careerRank < careermap[career] then
                -- info("不掉落4，" .. mboxCfg.itemid .. "careerRank < careermap[career]:", tostring(careerRank), tostring(careermap[career]))
                goto continue
            end
        end

        --获取掉落数量
        local count = string.split(mboxCfg.count, "#") or {}
        if #count == 2 then
            local min = tonumber(count[1])
            local max = tonumber(count[2])
            count = math.random(min, max)
        else
            count = count[1]
        end
        local itemid = mboxCfg.itemid;
        local dropBindCondition = mboxCfg.dropbindcondition
        --解绑
        if not string.isNullOrEmpty(dropBindCondition) then
            if ConditionManager.Check(actor, dropBindCondition) then
                local binditemid = ConfigDataManager.getTableValue('cfg_item', 'bindEqualItem', 'id', itemid)
                if not string.isNullOrEmpty(binditemid) then
                    itemid = tonumber(binditemid)
                end
            end
            -- local conditionSplit = string.split(dropBindCondition, "&")
            -- for i = 1, #conditionSplit do
            --     local condition = string.split(conditionSplit[i], "#")
            --     if ConditionHandler:triggerCheck(condition[1], actor, condition[2]) then
            --         local binditemid = ConfigDataManager.getTableValue('cfg_item', 'bindEqualItem', 'id', itemid)
            --         if not string.isNullOrEmpty(binditemid) then
            --             itemid = tonumber(binditemid)
            --         end
            --     end
            -- end
        end
        --获取掉落权重
        local weight = tonumber(mboxCfg.weight)
        total_weight = total_weight + weight
        --插入掉落列表
        table.insert(list, {
            itemid = itemid,
            count = count,
            weight = weight,
            cfg = mboxCfg
        })
        :: continue ::
    end
    -- info("掉落计算1，total_weight:", tostring(total_weight),"extractTimes:", tostring(extractTimes),"extract_pro:", tostring(extract_pro))
    if total_weight == 0 then
        return
    end
    -- info("掉落计算，total_weight:", tostring(total_weight),"extractTimes:", tostring(extractTimes),"extract_pro:", tostring(extract_pro))
    for i = 1, extractTimes + 1 do
        if i == extractTimes + 1 then
            if extract_pro > 0 then
                local randomNum = math.random(1, 100000000)
                -- info("extract_pro:", tostring(extract_pro),"randomNum:", tostring(randomNum))
                if randomNum > extract_pro then
                    break
                end
            else
                break
            end
        end
        local randomNum = math.random(1, total_weight)
        local currentWeight = 0
        for _, mboxCfg in pairs(list) do
            local weight = mboxCfg.weight
            currentWeight = currentWeight + weight
            if randomNum <= currentWeight then
                local itemId = tonumber(mboxCfg.itemid)
                -- info("掉落计算3，itemid:", tostring(mboxCfg.itemid), "count:", tostring(mboxCfg.count))
                dropItem[itemId] = (dropItem[itemId] or 0) + tonumber(mboxCfg.count)
                boxByItem[itemId] = mboxCfg.cfg
                break
            end
        end
    end
    return dropItem, boxByItem
end

---计算掉落归属
function this.SettingOwners(monsterActor, dieParam, bossDropCfgId, firstAttack)
    local owners = {}
    local mainOwner = firstAttack
    local mapId = tonumber(dieParam["mapid"])
    local dropType = tonumber(ConfigDataManager.getTableValue('cfg_boss_drop', 'droptype', 'id', bossDropCfgId))
    if dropType == DropType.NOT_OWNER then
        return mainOwner, owners
    elseif dropType == DropType.MAX_THREAT then
        local maxThreat = tonumber(dieParam["maxthreat"])
        mainOwner = maxThreat
    elseif dropType == DropType.LAST_ATTACK then
        local killerId = tonumber(dieParam["killer"])
        mainOwner = killerId
    elseif dropType == DropType.MAX_HURT then
        local maxHurtRid = tonumber(dieParam["maxhurt"])
        if maxHurtRid ~= nil and maxHurtRid > 0 then
            mainOwner = maxHurtRid
        end
    elseif dropType == DropType.PARTAKE then
        local threatList = dieParam["threatlist"]
        this.AddOwners(owners, threatList)
    elseif dropType == DropType.FIRST_ATTACK then
        mainOwner = firstAttack
    end

    table.insert(owners, mainOwner)
    --添加队友
    -- local ownerActor = getactor(mainOwner, mapId)
    -- local memberRids = Team.GetAllMemberRids(ownerActor)
    -- this.AddOwners(owners, memberRids)
    return mainOwner, owners
end

function this.AddOwners(owners, ridList)
    if table.isNullOrEmpty(ridList) then
        return
    end
    for _, rid in pairs(ridList) do
        if not table.contains(owners, rid) then
            table.insert(owners, rid)
        end
    end
end



---合并掉落道具
function this.MergeDropItem(dropItem, dropResult)
    --记录道具抽取次数
    for itemCfgId, timeCount in pairs(dropItem) do
        --怪物掉落结果
        this.MergeItemRecord(itemCfgId, timeCount, dropResult)
    end
end


function this.MergeItemRecord(itemCfgId, timeCount, itemRecord)
    local recordCount = itemRecord[itemCfgId]
    if recordCount == nil then
        recordCount = 0
    end
    itemRecord[itemCfgId] = recordCount + timeCount
end


