---更新怪物受击信息
function this.UpdateMonsterAttackInfo(targetActor, fightParam)
    local targetType = tonumber(fightParam["targettype"])
    if targetType ~= MapObjectType.MONSTER then
        return
    end
    local playerActor = nil
    local casterType = tonumber(fightParam["castertype"])
    if casterType == MapObjectType.PLAYER then
        playerActor = fightParam["caster"]
    end
    if casterType == MapObjectType.PET or casterType == MapObjectType.PARTNER then
        local masterId = tonumber(fightParam["masterid"])
        if masterId == nil or masterId == 0 then
            return
        end
        local mapId = tonumber(fightParam["mapid"])
        playerActor = getactor(masterId, mapId)
    end
    if playerActor == nil then
        return
    end
    local targetHurt = tonumber(fightParam["targethurt"])
    if targetHurt == nil or targetHurt < 0 then
        return 
    end
    this.addHurtList(targetActor, playerActor)
  


    this.TryUpdateMonsterFirstAttackInfoNew(targetActor, playerActor, fightParam)





end


--- 更新怪物首刀信息及怪物归属信息
function this.TryUpdateMonsterFirstAttackInfoNew(monsterActor, playerActor, fightParam)
    local monsterCfgId = tonumber(fightParam["targetcfgid"])
    
    local oldFirstCasterInfo = this.getFirstCasterInfo(monsterActor)

    local threatList = getthreatlist(monsterActor)
    local needResetFirstCaster = false

    if oldFirstCasterInfo.rid ~= nil then
        -- 不在仇恨列表
        local oldFirstCaster = getactor(playerActor, oldFirstCasterInfo.rid)
        local isInThreatList = false
        for _, threat in pairs(threatList) do
            if tostring(oldFirstCasterInfo.rid) == tostring(threat.target) then
                isInThreatList = true
                break
            end
        end
        if not isInThreatList then
            needResetFirstCaster = true
        end

        -- 玩家死亡
        if needResetFirstCaster == false then
            if isdead(oldFirstCaster) then
                needResetFirstCaster = true
            end
        end

        -- 玩家超出怪物的攻击距离
        if needResetFirstCaster == false then
            local birthPoint = getmonsterbirthpoint(monsterActor)
            local casterX = getbaseinfo(oldFirstCaster,"x")
            local casterY = getbaseinfo(oldFirstCaster,"y")
            local dis = HookCommonUtils.distance(casterX, casterY, birthPoint.x, birthPoint.y)
            local ai = ConfigDataManager.getTableValue("cfg_monster", "ai", "id", monsterCfgId)
            local aiConfig = ConfigDataManager.getById("cfg_monster_ai", ai)
            if dis>string.tonumber(aiConfig.leavebasedistance) then
                needResetFirstCaster = true
            end
        end
    else
        needResetFirstCaster = true
    end

    if needResetFirstCaster == true then
        local newCasterInfo = { rid = playerActor:toString(), name = getbaseinfo(playerActor, "rolename"), startTime = getbaseinfo("nowsec") }
        --保存首刀玩家信息
        this.setFirstCasterInfo(monsterActor, newCasterInfo)
    end

    local send = this.NeedSendOwnerMsg(monsterCfgId)
    if send then
        local oldRecord = this.getOwnerInfoRecord(monsterActor)
        local ownerType = string.tonumber(ConfigDataManager.getTableValue("cfg_monster", "droptype", "id", monsterCfgId))
        local ownerRid = this.getMonsterOwnerRid(monsterActor, ownerType)
        if oldRecord.rid == nil and ownerRid ~= nil then
            this.setOwnerInfoRecord(monsterActor, { rid = ownerRid })
            this.SendFirstAttackOwnerMsg(nil, monsterActor, { rid = playerActor:toString(), name = getbaseinfo(playerActor, "rolename"), ownerType = ownerType ,monsterId = monsterActor:toString()})
        else

            if tostring(oldRecord.rid) ~= ownerRid and ownerRid ~= nil then
                this.setOwnerInfoRecord(monsterActor, { rid = ownerRid })
                local owner = getactor(playerActor, ownerRid)
                this.SendFirstAttackOwnerMsg(nil, monsterActor, { rid = ownerRid, name = getbaseinfo(owner, "rolename"), ownerType = ownerType, monsterId = monsterActor:toString() })
            end
        end
    end

end


function this.getMonsterOwnerRid(monsterActor, ownerType)
    local ownerId = nil
    local threatList = getthreatlist(monsterActor)
    -- if ownerType == DropType.NOT_OWNER then

    if ownerType == DropType.MAX_THREAT then
        -- 根据仇恨大小排序
        if not table.isNullOrEmpty(threatList) then
            local maxThreatTarget = nil
            local maxThreatValue = -1
            for _, threatInfo in pairs(threatList) do
                local threatValue = tonumber(threatInfo.threat) or 0
                if threatValue > maxThreatValue then
                    maxThreatValue = threatValue
                    maxThreatTarget = threatInfo.target
                end
            end
            if maxThreatTarget ~= nil then
                ownerId = tostring(maxThreatTarget)
            end
        end
    -- elseif ownerType == DropType.LAST_ATTACK then
    elseif ownerType == DropType.MAX_HURT then
        -- 根据伤害大小排序
        if not table.isNullOrEmpty(threatList) then
            local maxThreatTarget = nil
            local maxThreatValue = -1
            for _, threatInfo in pairs(threatList) do
                local threatValue = tonumber(threatInfo.hurt) or 0
                if threatValue > maxThreatValue then
                    maxThreatValue = threatValue
                    maxThreatTarget = threatInfo.target
                end
            end
            if maxThreatTarget ~= nil then
                ownerId = tostring(maxThreatTarget)
            end
        end
    -- elseif ownerType == DropType.PARTAKE then
    elseif ownerType == DropType.FIRST_ATTACK then
        local firstCaster = this.getFirstCasterInfo(monsterActor)
        if firstCaster.rid ~= nil then
            ownerId = firstCaster.rid
        end
    end
    return ownerId
end



---怪物进入视野
function MonsterScript.MonsterEnterView(actor, monsterActor, monsterCfgId)
    local send = this.NeedSendOwnerMsg(monsterCfgId)
    if not send then
        return
    end

    local ownerType = string.tonumber(ConfigDataManager.getTableValue("cfg_monster", "droptype", "id", monsterCfgId))
    local ownerRid = this.getMonsterOwnerRid(monsterActor, ownerType)
    local msg = { ownerType = ownerType, monsterId = monsterActor:toString()}
    if ownerRid ~= nil then
        local owner = getactor(actor, ownerRid)
        msg = { rid = ownerRid, name = getbaseinfo(owner, "rolename"), ownerType = ownerType ,monsterId = monsterActor:toString()}
    end

    this.SendFirstAttackOwnerMsg(actor, monsterActor, msg)
end

---是否通知客户端归属信息
function this.NeedSendOwnerMsg(monsterCfgId)
    local monsterType = tonumber(ConfigDataManager.getTableValue("cfg_monster", "type", "id", monsterCfgId))
    if monsterType == nil or monsterType == MonsterType.NORMAL then
        return false
    end
    return true
end

---发送首刀归属信息
function this.SendFirstAttackOwnerMsg(actor, targetActor, ownerInfo)
    
    if actor == nil then
        sendrefluamsg(targetActor, LuaMessageIdToClient.RES_MONSTER_FIRST_ATTACK_OWNER_CHANGE, ownerInfo)
    else
        sendluamsg(actor, LuaMessageIdToClient.RES_MONSTER_FIRST_ATTACK_OWNER_CHANGE, ownerInfo)
    end
end



function this.addHurtList(monsterActor, playerActor)
    local monData = MonsterExtData.get(monsterActor)
    local beAttackedList = monData.beAttackedList or {}
    local rid = tonumber(getbaseinfo(playerActor, "rid"))
    if beAttackedList[rid] then
        return
    end
    beAttackedList[rid] = true
    monData.beAttackedList = beAttackedList
    monData:save(monsterActor)
end



---仇恨目标是否为最大伤害
function this.IsMaxHurtTarget(monsterCfgId)
    local threatType = tonumber(ConfigDataManager.getTableValue("cfg_monster_ai", "hate", "id", monsterCfgId))
    if threatType == nil then
        return false
    end
    if threatType == ThreatType.MAX_HURT then
        return true
    end
    return false
end

---使用掉落倍率道具
function MonsterScript.useDropRateItem(actor, itemConfigId, count)
    local config = ConfigDataManager.getById("cfg_item", itemConfigId)
    -- info("config", config)
    if table.isEmpty(config) or string.isNullOrEmpty(config.useparam) then
        return
    end
    if tonumber(config.type) ~= 3 or tonumber(config.subtype) ~= 101 then
        return
    end
    --使用buff叠加buff
    -- info("使用掉落倍率道具", config.useparam)
    local buff_drop_rate_cache = getplaydef(actor, BUFF_DROP_RATE_CACHE) or {}
    local buffSplit = string.splitInt(config.useparam, "#")
    local buff_time = buffSplit[2] * 86400 * 1000
    if hasbuff(actor, buffSplit[1]) then
        local buffInfo = API.GetBuffInfo(actor, buffSplit[1])
        buff_time = buff_time + buffInfo.totaltime
        delbuff(actor, buffSplit[1])
    end
    local result = addbuff(actor, buffSplit[1], 1, nil, {
        buffTotalTime = buff_time, --单位毫秒
    })
    buff_drop_rate_cache[buffSplit[1]] = getbaseinfo(actor, "now") + buff_time
    setplaydef(actor, BUFF_DROP_RATE_CACHE, buff_drop_rate_cache)
    -- info("addbuff结果", result,buff_time)
end

--登录添加buff
function MonsterScript.loginAddBuff(actor)
    local buff_drop_rate_cache = getplaydef(actor, BUFF_DROP_RATE_CACHE) or {}
    local cur_time = getbaseinfo(actor, "now")
    for buff_id, time in pairs(buff_drop_rate_cache) do
        if time > cur_time then
            -- info("登录添加buff", buff_id, time-cur_time)
            addbuff(actor, buff_id, 1, nil, {
                buffTotalTime = time - cur_time, --单位毫秒
            })
        end
    end
end

function MonsterScript.monsterDieDropTip(actor, data)
    local monsterCfgId = data.monstercfgid
    local dropItems = data.dropitems
    for _, dropItem in pairs(dropItems) do
        local cfgId = dropItem.cfgid
        local luaExtData = dropItem.luaextdata
        if table.notEmpty(luaExtData) then
            local tip = luaExtData.dropTip or 0
            if tip > 0 then
                local killerId = luaExtData.killerId
                if killerId == nil or killerId < 1 then
                    error(actor, "归属玩家", actor, "掉落 击杀者为空 killerId", killerId)
                    return
                end
                local killer = getactor(killerId)
                local name = getbaseinfo(killer, "rolename")
                local mapName = getbaseinfo(killer, "maptitle")
                local equipName = ConfigDataManager.getTableValue("cfg_item", "name", "id", cfgId)
                local monsterName = ConfigDataManager.getTableValue("cfg_monster", "name", "id", monsterCfgId)
                local itemList = {}
                local itemInfo = ItemFactory.build(dropItem)
                table.insert(itemList, itemInfo)
                noticeTip.noticeinfo0(killer, tip, itemList, name, mapName, monsterName, equipName)
            end
        end
    end
end
